3	//! Recovery rehearsals against real local registries, run by `just verify-real`.
4	//!
5	//! Every registry is bound through `[registries]` in `callisto.toml` over `https://`, so the production registry
6	//! binding and its https rule are exercised unchanged: the registries serve a self-signed certificate that the
7	//! package managers trust through their own CA environment variables. A missing tool fails the test.
8	//!
9	//! Ignored by default because they need the registries `just verify-real-tools` installs.
10	
11	#[path = "common/local_registries.rs"]
12	mod local_registries;
13	#[path = "common/release_harness.rs"]
14	mod release_harness;
15	
16	use std::fs;
17	use std::path::{Path, PathBuf};
18	use std::process::Output;
19	use std::time::{Duration, Instant};
20	
21	use local_registries::*;
22	use release_harness::*;
23	
24	const DEPENDENCY: &str = "callisto-verify-dependency";
25	const DEPENDENT: &str = "callisto-verify-dependent";
26	const PYPI_PACKAGE: &str = "callisto-verify-py";
27	const PYPI_ORIGIN: &str = "https://github.com/example/pypi-registry-fixture.git";
28	
29	/// A released workspace, the intent planned from it, and the rig that runs it against real local registries.
30	struct Release {
31	    dir: tempfile::TempDir,
32	    external: tempfile::TempDir,
33	    intent: PathBuf,
34	    receipt: PathBuf,
35	    bare: PathBuf,
36	    rig: Rig,
37	    tls: Tls,
38	    forge_tag: String,
39	}
40	
41	impl Release {
42	    /// `fixture` is the sealed release commit; `tls` was generated before it so its ports could be written into it.
43	    fn new(fixture: (tempfile::TempDir, String), external: tempfile::TempDir, tls: Tls, origin: &str, tag: &str) -> Self {
44	        let (dir, release_commit) = fixture;
45	        let intent = external.path().join("release-intent.json");
46	        let plan = callisto(
47	            dir.path(),
48	            &[
49	                "release",
50	                "plan",
51	                "--from-release-commit",
52	                &release_commit,
53	                "--decision",
54	                DECISION_PATH,
55	                "--out",
56	                intent.to_str().unwrap(),
57	            ],
58	        );
59	        assert!(plan.status.success(), "release plan failed: {}", stderr_of(&plan));
60	
61	        let bare = bare_remote(external.path());
62	        let mut rig = Rig::new(external.path(), &release_commit);
63	        rig.real_git_push(&bare, origin);
64	        for (key, value) in tls.trust_env() {
65	            rig.set(key, &value);
66	        }
67	        // The rig's fake `cargo` must not stand in for the real one on PATH.
68	        fs::remove_file(rig.bin.join("cargo")).unwrap();
69	        let receipt = external.path().join("release-receipt.json");
70	        Self { dir, external, intent, receipt, bare, rig, tls, forge_tag: tag.to_owned() }
71	    }
72	
73	    fn root(&self) -> &Path {
74	        self.dir.path()
75	    }
76	
77	    fn execute(&self) -> Output {
78	        execute_rig(self.root(), &self.intent, &self.receipt, &self.rig, &self.forge_tag, &[], None)
79	    }
80	
81	    fn remote_has_tag(&self, tag: &str) -> bool {
82	        git(&self.bare, &["tag", "--list", tag]).contains(tag)
83	    }
84	
85	    fn failure_context(&self, output: &Output) -> String {
86	        format!(
87	            "stderr:\n{}\neffect log:\n{}",
88	            stderr_of(output),
89	            fs::read_to_string(&self.rig.log).unwrap_or_default()
90	        )
91	    }
92	
93	    fn assert_failed_with(&self, output: &Output, code: &str) {
94	        assert!(!output.status.success(), "the run must fail\n{}", self.failure_context(output));
95	        assert!(
96	            stderr_of(output).contains(&format!("\"code\": \"{code}\"")),
97	            "expected {code}\n{}",
98	            self.failure_context(output)
99	        );
100	        assert!(!self.receipt.exists(), "a failed run must leave no terminal receipt");
101	    }
102	
103	    fn assert_completed(&self, output: &Output) {
104	        assert!(output.status.success(), "the run must complete\n{}", self.failure_context(output));
105	        assert!(self.receipt.exists(), "a completed run must write a receipt");
106	    }
107	}
