109	// ----------------------------------------------------------------------- npm
110	
111	/// A released npm workspace bound to one TLS Verdaccio.
112	struct NpmRelease {
113	    release: Release,
114	    port: u16,
115	}
116	
117	impl NpmRelease {
118	    fn new() -> Self {
119	        let external = tempfile::tempdir().unwrap();
120	        let tls = Tls::generate(external.path());
121	        let port = free_loopback_port();
122	        let fixture = npm_release_fixture(
123	            &[(DEPENDENCY, &[]), (DEPENDENT, &[DEPENDENCY])],
124	            &format!("\n[registries.npm]\nurl = \"https://127.0.0.1:{port}/\"\nconfirm-timeout = \"20s\"\n"),
125	        );
126	        fs::write(
127	            fixture.0.path().join(".npmrc"),
128	            format!("//127.0.0.1:{port}/:_authToken=callisto-verify-token\n"),
129	        )
130	        .unwrap();
131	        let release = Release::new(fixture, external, tls, NPM_ORIGIN, &format!("{DEPENDENT}@0.2.0"));
132	        Self { release, port }
133	    }
134	
135	    fn registry(&self, packages: &str) -> ServerGuard {
136	        start_verdaccio_with(self.release.external.path(), "npm", self.port, Some(&self.release.tls), packages)
137	    }
138	
139	    /// The versions the registry holds for `package`.
140	    fn versions(&self, package: &str) -> Vec<String> {
141	        let url = format!("https://127.0.0.1:{}/{package}", self.port);
142	        let raw = std::process::Command::new("curl")
143	            .args(["-sS", "-w", "\n%{http_code}", &url])
144	            .envs(self.release.tls.trust_env())
145	            .output()
146	            .expect("curl must be runnable");
147	        let text = String::from_utf8_lossy(&raw.stdout).into_owned();
148	        let (body, status) = text.rsplit_once('\n').unwrap();
149	        if status == "404" {
150	            return Vec::new();
151	        }
152	        let metadata: serde_json::Value = serde_json::from_str(body).unwrap_or_else(|e| panic!("{e}: {text}"));
153	        metadata["versions"].as_object().unwrap().keys().cloned().collect()
154	    }
155	}
156	
157	/// Verdaccio refusing `DEPENDENT` stands for a registry that dies after the first package is published.
158	fn refusing_the_dependent() -> String {
159	    format!(
160	        "packages:\n  '{DEPENDENT}':\n    access: $all\n    publish: nobody\n  '**':\n    access: $all\n    publish: $all\n    unpublish: $all\n"
161	    )
162	}
