164	#[test]
165	#[ignore = "needs local registries; run via `just verify-real`"]
166	fn a_partial_npm_publish_is_adopted_by_the_rerun_without_republishing() {
167	    let npm = NpmRelease::new();
168	    let release = &npm.release;
169	
170	    {
171	        let _registry = npm.registry(&refusing_the_dependent());
172	        let output = release.execute();
173	        assert!(
174	            !output.status.success(),
175	            "the registry refuses {DEPENDENT}, so the run must fail\n{}",
176	            release.failure_context(&output)
177	        );
178	        assert!(!release.receipt.exists(), "a failed run must leave no terminal receipt");
179	        assert_eq!(npm.versions(DEPENDENCY), ["0.2.0"], "the dependency published before the failure");
180	        assert!(npm.versions(DEPENDENT).is_empty(), "the refused package must not exist");
181	    }
182	
183	    let _registry = npm.registry(VERDACCIO_OPEN_ACCESS);
184	    let second = release.execute();
185	    release.assert_completed(&second);
186	    assert!(
187	        stderr_of(&second).contains("already published"),
188	        "the rerun must adopt the dependency instead of publishing it again:\n{}",
189	        stderr_of(&second)
190	    );
191	    assert_eq!(npm.versions(DEPENDENCY), ["0.2.0"]);
192	    assert_eq!(npm.versions(DEPENDENT), ["0.2.0"]);
193	    for package in [DEPENDENCY, DEPENDENT] {
194	        assert!(release.remote_has_tag(&format!("{package}@0.2.0")), "{package} tag must reach the remote");
195	    }
196	}
