199	#[ignore = "needs local registries; run via `just verify-real`"]
200	fn a_remote_tag_on_another_commit_stops_the_release_with_a_conflict() {
201	    let npm = NpmRelease::new();
202	    let release = &npm.release;
203	    let _registry = npm.registry(VERDACCIO_OPEN_ACCESS);
204	    let other = git(release.root(), &["rev-parse", "HEAD~1"]);
205	    let tag = format!("{DEPENDENT}@0.2.0");
206	    git(
207	        release.root(),
208	        &["push", &format!("file://{}", release.bare.display()), &format!("{other}:refs/tags/{tag}")],
209	    );
210	
211	    let output = release.execute();
212	    release.assert_failed_with(&output, "E167");
213	    assert_eq!(
214	        git(&release.bare, &["rev-parse", &format!("refs/tags/{tag}^{{commit}}")]),
215	        other,
216	        "the foreign tag must be left as it was"
