220	// ---------------------------------------------------------------------- pypi
221	
222	/// A released Python package whose index (a JSON simple index) and upload endpoint (pypiserver) serve two directories
223	/// over TLS.
224	struct PypiRelease {
225	    release: Release,
226	    index_port: u16,
227	    upload_port: u16,
228	}
229	
230	impl PypiRelease {
231	    fn new(confirm_timeout: &str) -> Self {
232	        let external = tempfile::tempdir().unwrap();
233	        let tls = Tls::generate(external.path());
234	        let (index_port, upload_port) = (free_loopback_port(), free_loopback_port());
235	        let fixture = pypi_release_fixture(&format!(
236	            "\n[registries.pypi]\nurl = \"https://127.0.0.1:{index_port}/simple/\"\n\
237	             publish-url = \"https://127.0.0.1:{upload_port}/\"\nconfirm-timeout = \"{confirm_timeout}\"\n"
238	        ));
239	        let mut release = Release::new(fixture, external, tls, PYPI_ORIGIN, &format!("{PYPI_PACKAGE}@0.2.0"));
240	        let wheels = std::env::var("VERIFY_REAL_WHEELS").expect("`just verify-real` provides VERIFY_REAL_WHEELS");
241	        release
242	            .rig
243	            .set("TWINE_USERNAME", "callisto-verify")
244	            .set("TWINE_PASSWORD", "callisto-verify")
245	            // The isolated build installs its backend from this directory, never from the real index.
246	            .set("PIP_NO_INDEX", "1")
247	            .set("PIP_FIND_LINKS", &wheels)
248	            // Looks at 1.5 s, 6 s, ... instead of 15 s, 45 s, ...
249	            .set("__CALLISTO_TEST_SLEEP_SCALE", "0.1");
250	        Self { release, index_port, upload_port }
251	    }
252	
253	    fn index_dir(&self) -> PathBuf {
254	        self.release.external.path().join("pypi-index")
255	    }
256	
257	    fn upload_dir(&self) -> PathBuf {
258	        self.release.external.path().join("pypi-upload")
259	    }
260	
261	    fn servers(&self) -> (ServerGuard, ServerGuard) {
262	        let external = self.release.external.path();
263	        let tls = Some(&self.release.tls);
264	        (
265	            start_json_simple_index(external, "index", self.index_port, &self.index_dir(), &self.release.tls),
266	            start_pypiserver(external, "upload", self.upload_port, &self.upload_dir(), tls),
267	        )
268	    }
269	}
270	
271	fn files_in(dir: &Path) -> Vec<String> {
272	    let mut names: Vec<String> = fs::read_dir(dir)
273	        .map(|entries| entries.map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned()).collect())
274	        .unwrap_or_default();
275	    names.sort();
276	    names
277	}
278	
279	/// Copies every file of `from` that `to` lacks, as a mirror catching up.
280	fn copy_missing(from: &Path, to: &Path) {
281	    for entry in fs::read_dir(from).unwrap() {
282	        let path = entry.unwrap().path();
283	        let target = to.join(path.file_name().unwrap());
284	        if !target.exists() {
285	            fs::copy(&path, &target).unwrap();
286	        }
287	    }
288	}
289	
290	/// Polls until `ready` holds, then waits `then` before running `act`. Used from a mirror thread.
291	fn after(ready: impl Fn() -> bool, then: Duration, act: impl FnOnce()) {
292	    let deadline = Instant::now() + Duration::from_secs(60);
293	    while !ready() && Instant::now() < deadline {
294	        std::thread::sleep(Duration::from_millis(100));
295	    }
296	    std::thread::sleep(then);
297	    act();
298	}
299	
300	/// A released single-package Python workspace publishing to PyPI only.
301	fn pypi_release_fixture(registries: &str) -> (tempfile::TempDir, String) {
302	    let dir = tempfile::tempdir().unwrap();
303	    let root = dir.path();
304	    callisto_fixtures::git::init_repo(root);
305	    git(root, &["remote", "add", "origin", PYPI_ORIGIN]);
306	    fs::write(root.join("Cargo.toml"), "[workspace]\nmembers = []\nresolver = \"2\"\n").unwrap();
307	    fs::write(root.join(".gitignore"), "/pkg/dist/\n/pkg/build/\n*.egg-info/\n").unwrap();
308	    fs::create_dir_all(root.join("pkg/callisto_verify_py")).unwrap();
309	    fs::write(root.join("pkg/callisto_verify_py/__init__.py"), "\n").unwrap();
310	    fs::write(
311	        root.join("pkg/pyproject.toml"),
312	        format!(
313	            "[build-system]\nrequires = [\"setuptools>=61.0\"]\nbuild-backend = \"setuptools.build_meta\"\n\n\
314	             [project]\nname = \"{PYPI_PACKAGE}\"\nversion = \"0.1.0\"\ndescription = \"verify-real probe\"\n\
315	             requires-python = \">=3.8\"\n"
316	        ),
317	    )
318	    .unwrap();
319	    git(root, &["add", "."]);
320	    git(root, &["commit", "-m", "initial Python workspace"]);
321	
322	    let init = callisto(root, &["init", "--yes", "--versioning", "independent"]);
323	    assert!(init.status.success(), "init failed: {}", stderr_of(&init));
324	    let config_path = root.join("callisto.toml");
325	    let mut config = fs::read_to_string(&config_path).unwrap();
326	    config.push_str(&format!("\n[[package]]\nmatch = \"pypi/{PYPI_PACKAGE}\"\npublish-to = [\"pypi\"]\n"));
327	    config.push_str(registries);
328	    fs::write(&config_path, config).unwrap();
329	    git(root, &["add", "."]);
330	    git(root, &["commit", "-m", "configure callisto"]);
331	
332	    let add = callisto(
333	        root,
334	        &["add", "--package", &format!("pypi/{PYPI_PACKAGE}:minor"), "--summary", "Ship the verify-real probe"],
335	    );
336	    assert!(add.status.success(), "add failed: {}", stderr_of(&add));
337	    git(root, &["add", "."]);
338	    git(root, &["commit", "-m", "add release changeset"]);
339	
340	    let version = callisto(root, &["version", "--no-refresh-lockfiles", "--emit-decision", DECISION_PATH]);
341	    assert!(version.status.success(), "version failed: {}", stderr_of(&version));
342	    git(root, &["add", "-A"]);
343	    git(root, &["commit", "-m", "release the probe 0.2.0"]);
344	    let release_commit = git(root, &["rev-parse", "HEAD"]);
345	    git(root, &["checkout", "--detach", &release_commit]);
346	    (dir, release_commit)
347	}
