349	#[test]
350	#[ignore = "needs local registries; run via `just verify-real`"]
351	fn a_python_release_waits_for_a_delayed_index() {
352	    let pypi = PypiRelease::new("30s");
353	    let release = &pypi.release;
354	    let _servers = pypi.servers();
355	
356	    // The upload endpoint takes the files at once; the index shows them only after the first looks.
357	    let mirror = std::thread::spawn({
358	        let (upload, index) = (pypi.upload_dir(), pypi.index_dir());
359	        move || after(|| files_in(&upload).len() == 2, Duration::from_millis(2500), || copy_missing(&upload, &index))
360	    });
361	    let started = Instant::now();
362	    let output = release.execute();
363	    mirror.join().unwrap();
364	    release.assert_completed(&output);
365	    assert!(
366	        started.elapsed() > Duration::from_millis(2500),
367	        "the run must have waited for the index, not seen the files at once"
368	    );
369	    assert_eq!(files_in(&pypi.index_dir()), files_in(&pypi.upload_dir()));
370	}
