372	#[test]
373	#[ignore = "needs local registries; run via `just verify-real`"]
374	fn a_python_index_that_never_shows_the_upload_fails_and_the_rerun_adopts_it() {
375	    let pypi = PypiRelease::new("5s");
376	    let release = &pypi.release;
377	    let _servers = pypi.servers();
378	
379	    let first = release.execute();
380	    release.assert_failed_with(&first, "E157");
381	    assert_eq!(files_in(&pypi.upload_dir()).len(), 2, "both files were uploaded");
382	    assert!(files_in(&pypi.index_dir()).is_empty());
383	    let uploaded = files_in(&pypi.upload_dir());
384	
385	    copy_missing(&pypi.upload_dir(), &pypi.index_dir());
386	    let second = release.execute();
387	    release.assert_completed(&second);
388	    assert_eq!(files_in(&pypi.upload_dir()), uploaded, "the rerun must not upload again");
389	}
390	
391	#[test]
392	#[ignore = "needs local registries; run via `just verify-real`"]
393	fn a_python_release_with_a_missing_wheel_uploads_only_the_wheel() {
394	    let pypi = PypiRelease::new("5s");
395	    let release = &pypi.release;
396	    let _servers = pypi.servers();
397	
398	    let first = release.execute();
399	    release.assert_failed_with(&first, "E157");
400	    let files = files_in(&pypi.upload_dir());
401	    let sdist = files.iter().find(|name| name.ends_with(".tar.gz")).expect("an sdist").clone();
402	    let wheel = files.iter().find(|name| name.ends_with(".whl")).expect("a wheel").clone();
403	
404	    // The index and the upload store hold the sdist; the wheel is gone from both.
405	    fs::remove_file(pypi.upload_dir().join(&wheel)).unwrap();
406	    fs::copy(pypi.upload_dir().join(&sdist), pypi.index_dir().join(&sdist)).unwrap();
407	    let sdist_before = fs::read(pypi.upload_dir().join(&sdist)).unwrap();
408	
409	    let mirror = std::thread::spawn({
410	        let (upload, index, wheel) = (pypi.upload_dir(), pypi.index_dir(), wheel.clone());
411	        move || after(|| upload.join(&wheel).exists(), Duration::ZERO, || copy_missing(&upload, &index))
412	    });
413	    let second = release.execute();
414	    mirror.join().unwrap();
415	    release.assert_completed(&second);
416	    assert!(pypi.upload_dir().join(&wheel).exists(), "the missing wheel must be uploaded");
417	    assert_eq!(
418	        fs::read(pypi.upload_dir().join(&sdist)).unwrap(),
419	        sdist_before,
420	        "the sdist the index already held must not be uploaded again"
421	    );
422	}
