    let _registry = npm.registry(VERDACCIO_OPEN_ACCESS);
    let other = git(release.root(), &["rev-parse", "HEAD~1"]);
    let tag = format!("{DEPENDENT}@0.2.0");
    git(
        release.root(),
        &["push", &format!("file://{}", release.bare.display()), &format!("{other}:refs/tags/{tag}")],
    );

